// src/components/icons/kasupda-logo.tsx
import type { SVGProps } from 'react';
import { cn } from '@/lib/utils';

export function KasupdaLogo({ className, ...props }: SVGProps<SVGSVGElement>) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 100 100"
      // The className will set the 'color', which can be used by 'currentColor'
      // Defaulting to text-primary for the main circle color, can be overridden.
      className={cn("fill-current text-primary", className)}
      {...props}
    >
      {/* Outer circle representing the logo's main body */}
      {/* Using 'currentColor' for fill makes it adapt to the 'text-primary' or other text color class */}
      <circle cx="50" cy="50" r="45" fill="currentColor" />
      
      {/* Inner letter 'K' */}
      {/* Uses primary-foreground color for contrast against the primary-colored circle. */}
      <text
        x="50"
        y="50"
        textAnchor="middle"
        dominantBaseline="central"
        fontWeight="bold"
        fontSize="50" // Font size relative to viewBox dimensions
        fill="hsl(var(--primary-foreground))" // Directly using the HSL variable for foreground
      >
        K
      </text>
    </svg>
  );
}
